        return False, f"Error checking year validity for {entry['path']}: {e}"


# Map check names to functions
CHECK_FUNCTIONS = {
    "file_exists": check_file_exists,
    "not_empty": check_not_empty,
    "columns_match": check_columns_match,
    "non_empty_values": check_non_empty_values,
    "valid_coordinates": check_valid_coordinates,
    "score_range": check_score_range,
    "valid_year": check_valid_year,
}


def run_validation():
    """Run all validation checks and return the summary list."""
    results = []

    for entry in VALIDATION_FILES:
        file_label = entry["name"]
        for check_name in entry["checks"]:
            func = CHECK_FUNCTIONS.get(check_name)
            if func is None:
                results.append({
                    "check_name": f"{file_label}_{check_name}",
                    "passed": False,
                    "message": f"Unknown check: {check_name}",
                })
                continue

            passed, message = func(entry)
            results.append({
                "check_name": f"{file_label}_{check_name}",
                "passed": passed,
                "message": message,
            })

    return results


def main():
    output_path = "outputs/t14_validation_summary.json"
    results = run_validation()

    # Ensure output directory exists
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(results, f, indent=2, ensure_ascii=False)

    # Print summary to stdout
    total = len(results)
    passed = sum(1 for r in results if r["passed"])
    failed = total - passed
    print(f"Validation complete: {total} checks, {passed} passed, {failed} failed")

    if failed > 0:
        print("\nFailed checks:")
        for r in results:
            if not r["passed"]:
                print(f"  - {r['check_name']}: {r['message']}")
        sys.exit(1)
    else:
        print("\nAll checks passed.")
        sys.exit(0)


if __name__ == "__main__":
    main()

